import { FilePickerClosed, getFilePickerBuilder } from '@nextcloud/dialogs'
import { translate as t, translatePlural as n } from '@nextcloud/l10n'

/**
 * Mime types the picker offers. The server independently rejects anything that is not
 * `audio/*`, so this list only shapes what the user sees.
 */
const AUDIO_MIME_TYPES = [
	'audio/mpeg',
	'audio/mp4',
	'audio/aac',
	'audio/ogg',
	'audio/flac',
	'audio/x-flac',
	'audio/wav',
	'audio/x-wav',
	'audio/webm',
]

/** Give up on measuring a single file rather than making the user wait. */
const MEASURE_TIMEOUT_MS = 4000
/** How many files to measure at once. */
const MEASURE_CONCURRENCY = 4

/**
 * Open the Files picker filtered to audio.
 *
 * Closing it without choosing returns an empty array rather than throwing. The picker
 * reports that case as an exception — `pickNodes()` throws `FilePickerClosed("FilePicker:
 * No nodes selected")` — but from here it is an ordinary outcome, and every caller
 * treating it as one is what keeps "I changed my mind" from being reported as a failure.
 *
 * Callers should therefore treat a rejection as a real fault and surface it.
 *
 * @return {Promise<Array<{fileid: number, source: string, basename: string}>>} empty when
 *   the picker was dismissed
 */
export async function pickAudioFiles() {
	const picker = getFilePickerBuilder(t('music_radio', 'Add music to this channel'))
		.setMimeTypeFilter(AUDIO_MIME_TYPES)
		.setMultiSelect(true)
		.allowDirectories(false)
		// The confirm button is not optional. The picker renders exactly the buttons it
		// is given, so without this it opens a dialog with no way to complete the
		// selection at all — it looks like the picker simply does not work.
		.setButtonFactory((selected) => [{
			label: selected.length > 0
				? n('music_radio', 'Add %n track', 'Add %n tracks', selected.length)
				: t('music_radio', 'Add'),
			variant: 'primary',
			disabled: selected.length === 0,
			callback: () => {},
		}])
		.build()

	try {
		return await picker.pickNodes()
	} catch (error) {
		// Matched by type, not by name or message. `FilePickerClosed` is declared as an
		// empty `extends Error`, which never sets `.name` — so it reads as plain `'Error'`,
		// and its message ("FilePicker: No nodes selected") says nothing about closing or
		// cancelling. Testing either of those was what put a red "FilePicker: No nodes
		// selected" toast in front of anyone who opened the picker and thought better of it.
		if (error instanceof FilePickerClosed) {
			return []
		}

		throw error
	}
}

/**
 * Choose a folder from the user's files.
 *
 * Directories only, which the picker expresses as a mime-type filter — there is no
 * "folders" mode. Single selection, since this names one place.
 *
 * @param {string} title shown as the dialog's heading
 * @return {Promise<string|null>} the chosen path, or null if the picker was dismissed
 */
export async function pickFolder(title) {
	const picker = getFilePickerBuilder(title)
		.setMimeTypeFilter(['httpd/unix-directory'])
		.allowDirectories(true)
		.setMultiSelect(false)
		// Same reason as above: the picker renders exactly the buttons it is given, and
		// with none it opens a dialog that cannot be completed.
		.setButtonFactory(() => [{
			label: t('music_radio', 'Choose'),
			variant: 'primary',
			callback: () => {},
		}])
		.build()

	try {
		const nodes = await picker.pickNodes()

		return nodes[0]?.path ?? null
	} catch (error) {
		if (error instanceof FilePickerClosed) {
			return null
		}

		throw error
	}
}

/**
 * Best-effort duration measurement in the browser.
 *
 * The server reads durations out of the files themselves and that value wins; this is
 * only a fallback for files whose headers the server cannot parse (a known problem on
 * some external storages). Because it is a fallback, anything that fails or takes too
 * long is simply dropped rather than blocking the add.
 *
 * @param {Array<{fileid: number, source: string}>} nodes
 * @return {Promise<Object<number, number>>} fileId => duration in ms
 */
export async function measureDurations(nodes) {
	const hints = {}
	const queue = [...nodes]

	const worker = async () => {
		while (queue.length > 0) {
			const node = queue.shift()
			const ms = await measureOne(node.source)
			if (ms !== null) {
				hints[node.fileid] = ms
			}
		}
	}

	await Promise.all(
		Array.from({ length: Math.min(MEASURE_CONCURRENCY, nodes.length) }, worker),
	)

	return hints
}

/**
 * @param {string} src
 * @return {Promise<number|null>} duration in ms, or null if it could not be determined
 */
function measureOne(src) {
	return new Promise((resolve) => {
		const audio = new Audio()
		let settled = false

		const finish = (value) => {
			if (settled) {
				return
			}
			settled = true
			clearTimeout(timer)
			audio.removeAttribute('src')
			// Release the pending network request; without this the browser keeps
			// buffering files the user is not going to hear.
			audio.load()
			resolve(value)
		}

		const timer = setTimeout(() => finish(null), MEASURE_TIMEOUT_MS)

		audio.addEventListener('loadedmetadata', () => {
			// Streams of unknown length report Infinity.
			finish(Number.isFinite(audio.duration) ? Math.round(audio.duration * 1000) : null)
		})
		audio.addEventListener('error', () => finish(null))

		audio.preload = 'metadata'
		audio.src = src
	})
}
